-- landhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Noonu Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 700 residents"},{"label":"Size","value":"0.8 km long, 0.4 km wide"},{"label":"Distance from Male","value":"170 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat"},{"label":"Known For","value":"Excellent fishing, pristine beaches"},{"label":"Best For","value":"Culture seekers, anglers, budget travelers"}],"island_overview":["Located in the northern waters of Noonu Atoll, Landhoo Island offers visitors a genuine experience of traditional Maldivian island life. This peaceful local island combines natural beauty with authentic cultural experiences.","Landhoo is known for its laid-back atmosphere, excellent fishing grounds, and beautiful beaches. The island maintains its traditional character while welcoming visitors with genuine Maldivian hospitality.","What makes Landhoo special is its untouched environment, rich marine biodiversity, and the opportunity to experience local culture firsthand. Visitors enjoy affordable accommodations and unforgettable island experiences."],"island_sections":[{"heading":"Location & Map","paragraphs":["Landhoo Island is located in the northern part of Noonu Atoll, approximately 170 kilometers from Male. This location offers a peaceful retreat while still being accessible from the capital.","The island''s position provides excellent access to some of the best fishing grounds in the Maldives, as well as beautiful coral reefs for snorkeling and diving."]},{"heading":"Landhoo: Natural Beauty & Marine Life","paragraphs":["Landhoo Island is renowned for its stunning natural beauty, featuring powdery white sand beaches, crystal-clear waters, and vibrant marine ecosystems. The island offers an unspoiled tropical paradise perfect for relaxation and exploration."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Landhoo boasts beautiful beaches with soft white sand and crystal-clear waters perfect for swimming and relaxation."]},{"heading":"Excellent Snorkeling","paragraphs":["The island''s house reef features diverse marine life and colorful corals, accessible directly from the beach."]},{"heading":"Authentic Island Culture","paragraphs":["Experience genuine Maldivian hospitality and traditional island life in a peaceful setting."]},{"heading":"Sandbank Excursions","paragraphs":["Explore nearby uninhabited sandbanks for the ultimate desert island experience."]},{"heading":"Beach Highlights","paragraphs":["Landhoo''s coastal features include:"]},{"heading":"Marine Environment","paragraphs":["The island''s underwater world features:"]},{"heading":"Activities & Experiences","paragraphs":["Landhoo offers a variety of activities focused on marine adventures, cultural experiences, and natural exploration in a pristine environment."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals and tropical fish."]},{"heading":"Traditional Fishing","paragraphs":["Join local fishermen for authentic fishing experiences using traditional methods."]},{"heading":"Island Hopping","paragraphs":["Visit nearby islands and discover uninhabited sandbanks with pristine natural beauty."]},{"heading":"Cultural Experiences","paragraphs":["Immerse yourself in local community life and authentic Maldivian customs."]},{"heading":"Scuba Diving","paragraphs":["Discover world-class dive sites around Noonu Atoll with professional dive operators."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching."]},{"heading":"People & Community Life","paragraphs":["Landhoo is home to a close-knit community of approximately 700 residents who maintain traditional Maldivian ways of life. The island''s population is known for their warmth and hospitality."]},{"heading":"Daily Life","paragraphs":["Life on Landhoo follows natural island rhythms, with fishing and community activities central to daily life. The island maintains a peaceful, unhurried pace that reflects traditional values."]},{"heading":"Culture & Traditions","paragraphs":["Landhoo preserves authentic Maldivian cultural traditions including music, dance, and handicrafts. The community celebrates Islamic festivals with enthusiasm."]},{"heading":"Local Economy","paragraphs":["The island''s economy is based on fishing and increasingly tourism, with families engaging in traditional occupations while participating in the growing tourism sector."]}],"island_faqs":[{"question":"How do I get to Landhoo Island?","answer":"Landhoo can be reached by domestic flight to Maafaru Airport (55 minutes from Male) followed by a 20-minute speedboat ride. Seaplane transfers are also available but depend on weather conditions."},{"question":"What is the best time to visit Landhoo?","answer":"The best time is during the dry season from December to April when weather is most favorable, though the island can be visited year-round."}],"island_nearby_slugs":["foddhoo","manadhoo","velidhoo","miladhoo","maafaru","kendhikolhudhoo","magoodhoo","henbandhoo","kudafaree","lhohi","maalhendhoo"]}'::jsonb
where node_type = 'location' and slug = 'landhoo';


-- lhaimagu
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Shaviyani Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,100 residents"},{"label":"Size","value":"1.2 km long, 0.8 km wide"},{"label":"Distance from Male","value":"208 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Charming culture, lovely beaches, excellent traditions"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, tradition seekers, nature lovers"}],"island_overview":["Lhaimagu Island is a charming local island in Shaviyani Atoll that offers visitors a pleasant glimpse into traditional Maldivian life in the northern region of the archipelago. This lovely island combines natural beauty with an excellent atmosphere, providing an ideal destination for travelers seeking wonderful cultural experiences and charming tropical surroundings.","Known for its lovely beaches, charming coral reefs, and excellent marine biodiversity, Lhaimagu provides pleasant opportunities for snorkeling, swimming, and underwater exploration. The island''s pleasant community embraces visitors with traditional Maldivian warmth and shares their excellent way of life with charming hospitality.","What makes Lhaimagu special is its charming natural environment and pleasant northern location. Visitors can enjoy lovely beaches, explore rich marine ecosystems, and experience excellent island culture while staying in comfortable accommodations that showcase the charming Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Lhaimagu Island is charmingly located in the northern part of Shaviyani Atoll, approximately 208 kilometers from Male. This location provides a charming and pleasant experience in the northern Maldives, while maintaining excellent accessibility through seaplane transfers or domestic flights.","The island''s position offers excellent protection from strong currents while providing access to lovely coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Shaviyani Atoll in its most charming form."]},{"heading":"Lhaimagu: Charming Paradise & Marine Excellence","paragraphs":["Lhaimagu Island is blessed with exceptional natural beauty, featuring lovely white sand beaches, crystal-clear turquoise waters, and one of the most charming marine environments in Shaviyani Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a pleasant, excellent setting."]},{"heading":"Lovely White Sand Beaches","paragraphs":["Lhaimagu features charming white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and pleasant beach activities."]},{"heading":"Charming House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers pleasant snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Pleasant Island Community","paragraphs":["Experience the excellent spirit of traditional northern island life with friendly locals and charming Maldivian culture in a pleasant community setting."]},{"heading":"Excellent Cultural Heritage","paragraphs":["Discover the island''s rich cultural practices and learn about traditional customs that make this community charming in the northern Maldives."]},{"heading":"Beach Features","paragraphs":["Lhaimagu''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Lhaimagu feature:"]},{"heading":"Activities & Experiences","paragraphs":["Lhaimagu offers a perfect blend of marine adventures, cultural experiences, and charming activities. The island''s pleasant environment and excellent atmosphere provide ideal conditions for various activities in a lovely, wonderful setting."]},{"heading":"Charming House Reef Snorkeling","paragraphs":["Explore the pleasant house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in charming waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby lovely dive sites with professional dive operators offering guided dives and certification courses in charming marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, lovely sandbanks, and discover the natural beauty of Shaviyani Atoll with pleasant exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in charming community settings."]},{"heading":"Excellent Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience charming Maldivian island life with pleasant cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy lovely sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in charming waters."]},{"heading":"Community Life & Culture","paragraphs":["Lhaimagu is home to approximately 1,100 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and charming cultural traditions that create a pleasant atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Lhaimagu follows traditional patterns centered around fishing, culture, and community activities. The island maintains a charming atmosphere where visitors can experience pleasant Maldivian culture and customs in their most excellent, wonderful setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and cultural techniques. Visitors can observe and often participate in cultural activities and celebrations in this charming island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Lhaimagu has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and charming cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Lhaimagu Island?","answer":"Regular inter-island ferry services are also available between Shaviyani Atoll islands."},{"question":"What is the best time to visit Lhaimagu?","answer":"The best time to visit Lhaimagu is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more charming local atmosphere."},{"question":"What accommodation options are available on Lhaimagu?","answer":"Lhaimagu offers various accommodations including charming guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a pleasant setting."},{"question":"What makes Lhaimagu''s culture special?","answer":"Lhaimagu is known for its charming and pleasant cultural environment in the northern Maldives. The island maintains traditional Maldivian cultural practices while offering an excellent atmosphere perfect for wonderful exploration. Visitors can experience lovely cultural exchanges and participate in charming community activities."}],"island_nearby_slugs":["foakaidhoo","feydhoo","feevah","bileffahi","noomaraa","narudhoo","milandhoo","maroshi","maaungoodhoo","komandoo","kanditheemu","goidhoo","funadhoo"]}'::jsonb
where node_type = 'location' and slug = 'lhaimagu';


-- lhohi
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Noonu Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 700 residents"},{"label":"Size","value":"0.8 km long, 0.5 km wide"},{"label":"Distance from Male","value":"190 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Charming atmosphere, beautiful beaches, excellent snorkeling"},{"label":"Best For","value":"Cultural enthusiasts, beach lovers, snorkelers, families"}],"island_overview":["Lhohi Island is a charming local island in Noonu Atoll that offers visitors a delightful glimpse into authentic Maldivian life. This friendly island combines stunning natural beauty with a warm, welcoming atmosphere, providing an ideal destination for travelers seeking genuine cultural experiences and natural splendor.","Known for its beautiful beaches, crystal-clear lagoons, and excellent house reef, Lhohi provides wonderful opportunities for snorkeling, swimming, and marine exploration. The island''s friendly community welcomes visitors with traditional Maldivian warmth and shares their charming way of life with genuine enthusiasm.","What makes Lhohi special is its charming atmosphere and beautiful natural setting. Visitors can enjoy stunning beaches, explore diverse marine life, and experience traditional island culture while staying in comfortable accommodations that showcase the friendly Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Lhohi Island is strategically located in the northern part of Noonu Atoll, approximately 190 kilometers from Male. This location provides a charming and authentic experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to beautiful coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Noonu Atoll."]},{"heading":"Lhohi: Charming Paradise & Marine Wonders","paragraphs":["Lhohi Island is blessed with exceptional natural beauty, featuring pristine white sand beaches, crystal-clear turquoise waters, and one of the most charming marine environments in Noonu Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a friendly, welcoming setting."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Lhohi features stunning white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and charming beach activities."]},{"heading":"Charming House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers delightful snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Friendly Community Life","paragraphs":["Experience the charming spirit of traditional island life with friendly locals and warm Maldivian culture in a welcoming community setting."]},{"heading":"Charming Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and pristine islands around Lhohi for delightful tropical paradise experiences with beautiful marine life."]},{"heading":"Beach Features","paragraphs":["Lhohi''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Lhohi feature:"]},{"heading":"Activities & Experiences","paragraphs":["Lhohi offers a perfect blend of marine adventures, cultural experiences, and charming activities. The island''s friendly environment and welcoming atmosphere provide ideal conditions for various activities in a warm, inviting setting."]},{"heading":"Charming House Reef Snorkeling","paragraphs":["Explore the beautiful house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in friendly waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby beautiful dive sites with professional dive operators offering guided dives and certification courses in charming marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, pristine sandbanks, and discover the charming beauty of Noonu Atoll with friendly exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in friendly community settings."]},{"heading":"Charming Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience charming Maldivian island life with friendly cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in beautiful waters."]},{"heading":"Community Life & Culture","paragraphs":["Lhohi is home to approximately 700 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and charming cultural traditions that create a welcoming atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Lhohi follows traditional patterns centered around fishing, family, and community activities. The island maintains a charming atmosphere where visitors can experience authentic Maldivian culture and customs in their most friendly, welcoming setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this charming island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Lhohi has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and charming cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Lhohi Island?","answer":"Regular ferry services are also available from Male and nearby islands in Noonu Atoll."},{"question":"What is the best time to visit Lhohi?","answer":"The best time to visit Lhohi is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more charming local atmosphere."},{"question":"What accommodation options are available on Lhohi?","answer":"Lhohi offers various budget-friendly accommodations including charming guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a friendly setting."},{"question":"What makes Lhohi''s community special?","answer":"Lhohi is known for its charming and friendly community atmosphere. The island maintains authentic Maldivian cultural practices while welcoming visitors with warm hospitality. Visitors can experience genuine cultural exchanges and participate in community activities in this delightful setting."}],"island_nearby_slugs":["foddhoo","manadhoo","velidhoo","miladhoo","maafaru","landhoo","kendhikolhudhoo","magoodhoo","henbandhoo","kudafaree","maalhendhoo"]}'::jsonb
where node_type = 'location' and slug = 'lhohi';


-- maabaidhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Laamu Atoll, Southern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 800 residents"},{"label":"Size","value":"0.8 km long, 0.3 km wide"},{"label":"Distance from Male","value":"250 km"},{"label":"Transfer Options","value":"Domestic flight + ferry"},{"label":"Known For","value":"Authentic culture, pristine beaches, peacefulness"},{"label":"Best For","value":"Cultural travelers, budget travelers, snorkelers"}],"island_overview":["Located in the scenic Laamu Atoll, Maabaidhoo Island offers visitors an authentic Maldivian experience away from the crowds. This tranquil island maintains its traditional character while providing comfortable facilities for tourists seeking cultural immersion.","What makes Maabaidhoo special is its peaceful atmosphere, beautiful beaches, and rich cultural heritage. The island features powdery white sand beaches, crystal-clear turquoise waters, and a welcoming local community that preserves traditional ways of life.","Visitors to Maabaidhoo are drawn by its authentic island life, excellent snorkeling opportunities, cultural experiences, and budget-friendly accommodations. The island''s remote location provides a true escape from modern life."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maabaidhoo Island is situated in the southern part of Laamu Atoll, approximately 250 kilometers from Male. This remote location provides an authentic Maldivian experience away from the more touristy areas, with stunning natural beauty and traditional island life.","The island''s position offers protection from strong currents while still providing access to excellent snorkeling and diving sites. The surrounding waters feature healthy coral reefs and abundant marine life, making it a great destination for underwater exploration."]},{"heading":"Maabaidhoo: Natural Beauty & Beaches","paragraphs":["Maabaidhoo Island is renowned for its pristine beaches and untouched natural beauty, featuring white sand shores and healthy coral reefs. The island offers visitors a peaceful tropical paradise with excellent snorkeling and relaxation opportunities."]},{"heading":"Pristine White Sand Beaches","paragraphs":["The island features stunning white sand beaches with crystal-clear turquoise waters, offering the perfect setting for relaxation."]},{"heading":"Excellent Snorkeling","paragraphs":["Explore the vibrant house reef accessible from shore, featuring diverse marine life and coral formations perfect for snorkeling."]},{"heading":"Authentic Island Life","paragraphs":["Experience traditional Maldivian culture and hospitality in a peaceful setting away from tourist crowds."]},{"heading":"Sandbank Excursions","paragraphs":["Visit pristine uninhabited sandbanks for picnics, swimming, and the ultimate desert island experience."]},{"heading":"Beach Highlights","paragraphs":["Maabaidhoo''s beaches offer:"]},{"heading":"Marine Environment","paragraphs":["The island''s marine ecosystem features:"]},{"heading":"Activities & Experiences","paragraphs":["Maabaidhoo offers a variety of activities focused on marine adventures, cultural experiences, and relaxation. The island''s peaceful environment provides excellent opportunities for both adventure and tranquility."]},{"heading":"Snorkeling","paragraphs":["Explore the vibrant house reef directly from shore or join boat excursions to nearby coral gardens."]},{"heading":"Scuba Diving","paragraphs":["Discover underwater wonders at nearby dive sites with professional dive operators."]},{"heading":"Sandbank Visits","paragraphs":["Experience pristine uninhabited sandbanks for picnics and swimming in crystal-clear waters."]},{"heading":"Traditional Fishing","paragraphs":["Join local fishermen for traditional night fishing experiences under the stars."]},{"heading":"Cultural Experiences","paragraphs":["Engage with local community life and learn about traditional Maldivian culture."]},{"heading":"Beach Relaxation","paragraphs":["Enjoy the pristine beaches, perfect for sunbathing and leisurely walks."]},{"heading":"People & Community Life","paragraphs":["Maabaidhoo is home to a peaceful community of approximately 800 residents who maintain traditional Maldivian ways of life. The island''s population is known for their hospitality and strong community bonds."]},{"heading":"Daily Life","paragraphs":["Life on Maabaidhoo follows traditional Maldivian rhythms, beginning with morning prayers and continuing with fishing, small-scale agriculture, and community activities. The island maintains a relaxed atmosphere where traditional values are preserved."]},{"heading":"Culture & Traditions","paragraphs":["Maabaidhoo preserves authentic Maldivian cultural traditions including traditional music, dance, and crafts. The community celebrates Islamic festivals with enthusiasm and maintains traditional practices such as boat building and fishing techniques."]},{"heading":"Local Economy","paragraphs":["The island''s economy is based on fishing, agriculture, and increasingly tourism. Many families engage in traditional occupations while also participating in the growing tourism sector through guesthouses and tour services."]}],"island_faqs":[{"question":"How do I get to Maabaidhoo Island?","answer":"Maabaidhoo Island can be reached by domestic flight to Kadhdhoo Airport (1 hour from Male) followed by a 45-minute ferry ride. Direct seaplane transfers from Male are also available but more expensive. There is also a weekly public ferry from Male that takes 16-18 hours."},{"question":"What is the best time to visit Maabaidhoo?","answer":"The best time to visit is during the dry season from December to April when the weather is sunny and rainfall is minimal. However, the island can be visited year-round, with the wet season (May-November) offering fewer crowds and lower prices."},{"question":"What makes Maabaidhoo special?","answer":"Maabaidhoo offers an authentic Maldivian experience away from tourist crowds, with pristine beaches, excellent snorkeling, and a peaceful atmosphere. The island maintains strong traditional culture while welcoming visitors."},{"question":"Are there restaurants on Maabaidhoo?","answer":"Yes, there are small local restaurants and cafes serving Maldivian cuisine. Most guesthouses also offer meal packages featuring fresh local seafood and traditional dishes."}],"island_nearby_slugs":["fonadhoo","gan","mundoo","isdhoo","kunahandhoo","dhanbidhoo","hithadhoo","maamendhoo","maavah"]}'::jsonb
where node_type = 'location' and slug = 'maabaidhoo';


-- maaenboodhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Maaenboodhoo Island?","answer":"Public ferry service operates weekly from Male (approximately 10-12 hours journey time). Private speedboat transfers can be arranged through guesthouses (approximately 4-5 hours from Male). Most accommodations can assist with arranging transportation."},{"question":"What is the best time to visit Maaenboodhoo Island?","answer":"The best time to visit Maaenboodhoo Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas. This period is ideal for water activities, with excellent visibility for snorkeling and diving. The southwest monsoon (May to November) brings occasional rain showers but also lower prices and fewer tourists. Water temperature remains warm (27-30C/80-86F) throughout the year."},{"question":"What makes Maaenboodhoo different from other local islands in the Maldives?","answer":"Maaenboodhoo stands out for its exceptional preservation of traditional Maldivian life in Dhaalu Atoll. Unlike more developed islands, Maaenboodhoo maintains its authentic character with a community still primarily engaged in traditional fishing and crafts. The island offers access to Dhaalu Atoll''s spectacular marine life while providing a genuine cultural experience away from mass tourism. Its small size and limited visitor numbers create an intimate atmosphere where travelers can truly connect with local culture and lifestyle."},{"question":"Are there any dress code requirements on Maaenboodhoo Island?","answer":"As Maaenboodhoo is a local inhabited island with a Muslim population, visitors are expected to dress modestly in public areas (shoulders and knees covered). Swimwear is only permitted at the designated \"bikini beach.\" When visiting the mosque or religious sites, women should cover their heads. These requirements don''t apply during water activities or at resort day visits. Respecting local dress codes is an important way to show cultural sensitivity during your stay."},{"question":"What marine life can I expect to see while snorkeling around Maaenboodhoo?","answer":"Maaenboodhoo''s waters offer excellent marine biodiversity, including healthy coral formations with both hard and soft corals. Common sightings include reef sharks (particularly blacktip and whitetip), sea turtles, various ray species, and abundant reef fish including parrotfish, angelfish, butterflyfish, and triggerfish. The house reef provides easy access to this underwater world directly from shore, while boat excursions can take you to nearby thilas (underwater pinnacles) that attract even more diverse marine life."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'maaenboodhoo';


-- maafaru
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Noonu Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island with International Airport"},{"label":"Population","value":"Approximately 2,500 residents"},{"label":"Size","value":"2.1 km long, 1.2 km wide"},{"label":"Distance from Male","value":"180 km"},{"label":"Transfer Options","value":"Direct flights to Maafaru Airport or seaplane"},{"label":"Known For","value":"International airport, strategic location, convenient access"},{"label":"Best For","value":"Gateway travelers, convenience seekers, cultural enthusiasts"}],"island_overview":["Maafaru Island is a strategic gateway island in Noonu Atoll that offers visitors convenient access to authentic Maldivian life. This important island combines modern infrastructure with natural beauty, providing an ideal destination for travelers seeking both convenience and genuine cultural experiences.","Known for its international airport, stunning beaches, crystal-clear lagoons, and excellent house reef, Maafaru provides exceptional opportunities for snorkeling, swimming, and marine exploration. The island''s welcoming community embraces visitors with traditional Maldivian warmth while offering modern conveniences.","What makes Maafaru special is its strategic location and gateway status. Visitors can enjoy convenient access to beautiful beaches, explore diverse marine life, and experience traditional island culture while benefiting from modern facilities and easy connectivity to other Noonu Atoll islands."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maafaru Island is strategically located in the northern part of Noonu Atoll, approximately 180 kilometers from Male. This location provides convenient and strategic access while serving as the main gateway to Noonu Atoll through its international airport facility.","The island''s position offers excellent connectivity to other islands in the atoll while providing access to stunning coral reefs and diverse marine ecosystems. Its strategic location makes it an ideal base for exploring the beauty and cultural richness of Noonu Atoll."]},{"heading":"Maafaru: Strategic Paradise & Gateway Beauty","paragraphs":["Maafaru Island is blessed with exceptional natural beauty, featuring pristine white sand beaches, crystal-clear turquoise waters, and one of the most strategic marine environments in Noonu Atoll. The island offers perfect conditions for beach relaxation and marine exploration with convenient modern facilities."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Maafaru features stunning white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and convenient beach activities."]},{"heading":"Strategic House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers convenient snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Strategic Community Life","paragraphs":["Experience the convenient spirit of traditional island life with friendly locals and strategic Maldivian culture in a modern community setting."]},{"heading":"Strategic Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and pristine islands around Maafaru for convenient tropical paradise experiences with strategic marine access."]},{"heading":"Beach Features","paragraphs":["Maafaru''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Maafaru feature:"]},{"heading":"Activities & Experiences","paragraphs":["Maafaru offers a perfect blend of marine adventures, cultural experiences, and strategic activities. The island''s convenient environment and gateway atmosphere provide ideal conditions for various activities with modern facilities and easy connectivity."]},{"heading":"Strategic House Reef Snorkeling","paragraphs":["Explore the convenient house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility with easy access."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby convenient dive sites with professional dive operators offering guided dives and certification courses in strategic marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, pristine sandbanks, and discover the strategic beauty of Noonu Atoll with convenient exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in strategic community settings."]},{"heading":"Strategic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience convenient Maldivian island life with strategic cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in convenient waters."]},{"heading":"Community Life & Culture","paragraphs":["Maafaru is home to approximately 2,500 residents who maintain traditional Maldivian ways of life while embracing modern development and tourism. The island''s community is known for their exceptional friendliness, hospitality, and strategic cultural traditions that create a convenient atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Maafaru follows traditional patterns centered around fishing, family, and community activities, enhanced by modern infrastructure. The island maintains a strategic atmosphere where visitors can experience authentic Maldivian culture with convenient modern amenities."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this strategic island environment."]},{"heading":"Modern Development","paragraphs":["Maafaru has embraced modern development including the international airport while preserving the island''s natural environment and strategic cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Maafaru Island?","answer":"The island serves as the main gateway to Noonu Atoll with excellent connectivity to other islands in the atoll."},{"question":"What is the best time to visit Maafaru?","answer":"The best time to visit Maafaru is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more strategic local atmosphere."},{"question":"What accommodation options are available on Maafaru?","answer":"Maafaru offers various accommodations including strategic guesthouses, airport hotels, and budget-friendly options. Most accommodations offer modern amenities and convenient airport access."},{"question":"What makes Maafaru special as a gateway island?","answer":"Maafaru is special for its strategic location and international airport facility, making it the main gateway to Noonu Atoll. The island combines modern infrastructure with authentic Maldivian culture, offering convenient access to traditional island experiences and easy connectivity to other atoll islands."}],"island_nearby_slugs":["foddhoo","manadhoo","velidhoo","miladhoo","landhoo","kendhikolhudhoo","magoodhoo","henbandhoo","kudafaree","lhohi","maalhendhoo"]}'::jsonb
where node_type = 'location' and slug = 'maafaru';


-- maafushi
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Kaafu Atoll, South Male Atoll"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 2,500 residents"},{"label":"Size","value":"1.2 km long, 0.3 km wide"},{"label":"Distance from Male","value":"27 km"},{"label":"Transfer Options","value":"Public ferry, speedboat"},{"label":"Known For","value":"Budget travel, water sports, vibrant nightlife"},{"label":"Best For","value":"Budget travelers, adventure seekers, social atmosphere"}],"island_overview":["Located in the heart of Kaafu Atoll approximately 27 kilometers from Male, Maafushi Island stands as the most popular and developed local island destination in the Maldives. This vibrant island has successfully transformed from a traditional fishing community into a thriving tourism hub while maintaining its authentic Maldivian character and warm hospitality.","What makes Maafushi truly special is its perfect combination of affordability, adventure, and authentic experiences. The island offers the widest range of budget-friendly accommodations, water sports activities, and dining options among all local islands, making it the ideal destination for travelers seeking the Maldivian experience without the luxury resort price tag.","Visitors to Maafushi are drawn by its excellent value for money, diverse activity options, vibrant social atmosphere, beautiful beaches, and convenient accessibility. The island has become synonymous with budget travel in the Maldives, offering everything from thrilling water sports to peaceful beach relaxation and cultural immersion."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maafushi Island is strategically located in the southern part of Kaafu Atoll (South Male Atoll), approximately 27 kilometers from Male. This prime location provides excellent accessibility while offering access to pristine coral reefs, diverse marine life, and numerous nearby attractions including sandbanks and uninhabited islands.","The island''s position in the atoll provides protection from strong ocean swells while still offering access to excellent snorkeling and diving sites. The surrounding lagoon features crystal-clear waters with good visibility, making it perfect for water sports and marine activities throughout the year."]},{"heading":"Maafushi: Water Sports & Adventure Paradise","paragraphs":["Maafushi Island is renowned as the water sports capital of the Maldives'' local islands, offering the most comprehensive range of marine activities, adventure sports, and excursions. The island''s developed tourism infrastructure ensures high-quality experiences at budget-friendly prices."]},{"heading":"Comprehensive Water Sports","paragraphs":["Extensive range of water sports including jet skiing, parasailing, windsurfing, kayaking, catamaran sailing, and banana boat rides with professional operators and modern equipment."]},{"heading":"Diving & Snorkeling","paragraphs":["Multiple dive centers offering courses and excursions to nearby reefs, with excellent snorkeling opportunities both from shore and on organized boat trips to pristine sites."]},{"heading":"Island Hopping & Excursions","paragraphs":["Daily excursions to pristine sandbanks, uninhabited islands, and nearby resorts, offering diverse experiences from picnic trips to sunset cruises and dolphin watching."]},{"heading":"Beautiful Beaches","paragraphs":["Stunning white sand beaches with designated bikini beach areas for tourists, perfect for swimming, sunbathing, and beach sports in a relaxed, social atmosphere."]},{"heading":"Water Sports Activities","paragraphs":["Maafushi offers the most comprehensive water sports menu:"]},{"heading":"Excursion Options","paragraphs":["Daily excursions and adventure trips include:"]},{"heading":"Activities & Experiences","paragraphs":["Maafushi offers the most diverse range of activities among all local islands, combining thrilling water sports, cultural experiences, relaxation options, and vibrant nightlife. The island caters to all types of travelers from adventure seekers to culture enthusiasts."]},{"heading":"Water Sports Adventures","paragraphs":["Experience the full range of water sports from jet skiing and parasailing to windsurfing and catamaran sailing with professional operators."]},{"heading":"Diving & Snorkeling","paragraphs":["Explore vibrant coral reefs and diverse marine life with multiple dive centers offering courses and excursions for all experience levels."]},{"heading":"Island Hopping","paragraphs":["Visit pristine sandbanks, uninhabited islands, and nearby resorts on daily excursions with snorkeling, swimming, and beach activities."]},{"heading":"Fishing Experiences","paragraphs":["Join traditional night fishing trips or exciting big game fishing adventures with experienced local fishermen and modern equipment."]},{"heading":"Cultural Immersion","paragraphs":["Experience authentic Maldivian culture through local interactions, traditional crafts, music performances, and community visits."]},{"heading":"Beach & Relaxation","paragraphs":["Enjoy beautiful beaches, spa treatments, yoga sessions, and peaceful moments in designated tourist areas with modern facilities."]},{"heading":"People & Community Life","paragraphs":["Maafushi is home to a dynamic community of approximately 2,500 residents who have successfully embraced tourism while preserving their cultural identity. The island represents one of the most successful examples of community-based tourism in the Maldives, where local entrepreneurship and traditional values coexist harmoniously."]},{"heading":"Tourism Pioneer","paragraphs":["As the first local island to develop comprehensive tourism infrastructure, Maafushi has become a model for sustainable island tourism. The community has invested heavily in education, language skills, and hospitality training, creating a generation of skilled tourism professionals who understand both local culture and international visitor expectations."]},{"heading":"Entrepreneurial Spirit","paragraphs":["The island showcases remarkable entrepreneurial energy, with many residents operating guesthouses, restaurants, dive centers, and tour companies. This local ownership ensures that tourism benefits flow directly to the community, creating employment opportunities and supporting local economic development."]},{"heading":"Cultural Balance","paragraphs":["Despite rapid tourism development, Maafushi maintains its cultural traditions and Islamic values. The community has successfully created designated tourist areas while preserving local neighborhoods, allowing visitors to experience authentic Maldivian life while respecting local customs and privacy."]}],"island_faqs":[{"question":"Why is Maafushi considered the best budget destination in the Maldives?","answer":"Maafushi offers the most comprehensive tourism infrastructure among local islands, with the widest range of budget accommodations, restaurants, and activities. The island provides excellent value for money with modern amenities, professional services, and competitive prices. Its developed tourism industry ensures high standards while maintaining affordability, making it possible to experience the Maldives without luxury resort costs."},{"question":"What water sports and activities are available on Maafushi?","answer":"Maafushi offers the most extensive range of water sports in the local islands, including jet skiing, parasailing, windsurfing, kayaking, catamaran sailing, banana boat rides, diving, snorkeling, fishing trips, and dolphin watching. The island has multiple professional operators with modern equipment, ensuring safe and enjoyable experiences. Daily excursions to sandbanks, uninhabited islands, and nearby resorts are also available."},{"question":"How do I get to Maafushi Island?","answer":"Maafushi is easily accessible by public ferry or speedboat from Male. Most accommodations can arrange transfers, and seaplane options are available for a premium experience."},{"question":"What accommodation options are available on Maafushi?","answer":"Options include backpacker hostels, budget guesthouses, mid-range hotels, and boutique properties with resort-style amenities. Most accommodations offer air conditioning, WiFi, and can arrange activities and transfers. The island''s developed infrastructure ensures comfortable stays at all price levels."}],"island_nearby_slugs":["himmafushi","huraa","dhiffushi","gulhi","guraidhoo","hulhumale","male","kaashidhoo","gaafaru"]}'::jsonb
where node_type = 'location' and slug = 'maafushi';


-- maakurathu
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Raa Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 500 residents"},{"label":"Size","value":"0.5 km long, 0.3 km wide"},{"label":"Distance from Male","value":"175 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat"},{"label":"Known For","value":"Peaceful atmosphere, excellent fishing, beautiful beaches"},{"label":"Best For","value":"Cultural travelers, budget travelers, fishing enthusiasts"}],"island_overview":["Nestled in the northern waters of Raa Atoll, Maakurathu Island offers visitors a glimpse into traditional Maldivian island life away from the crowds. This charming local community maintains its authentic character while welcoming visitors with genuine hospitality.","Maakurathu stands out for its laid-back atmosphere, excellent fishing grounds, and beautiful beaches. The island''s compact size makes it easy to explore on foot, while the surrounding waters offer excellent snorkeling opportunities.","What makes Maakurathu special is its peaceful environment, where visitors can experience the rhythm of daily island life while enjoying comfortable accommodations and delicious local cuisine."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maakurathu Island is located in the northern part of Raa Atoll, approximately 175 kilometers from Male. This location offers visitors a more remote and authentic experience compared to more tourist-heavy areas.","The island''s position provides natural protection from strong currents while maintaining access to excellent fishing grounds in the surrounding waters."]},{"heading":"Maakurathu: Natural Beauty & Marine Life","paragraphs":["Maakurathu Island is blessed with beautiful beaches, crystal-clear waters, and a vibrant marine environment. The island offers an unspoiled tropical setting perfect for relaxation and exploration."]},{"heading":"Secluded Beaches","paragraphs":["Maakurathu boasts beautiful stretches of white sand beach with calm, clear waters perfect for swimming."]},{"heading":"Marine Exploration","paragraphs":["The island''s house reef offers good snorkeling with diverse marine life and coral formations."]},{"heading":"Authentic Island Life","paragraphs":["Experience genuine Maldivian hospitality and traditional island culture in a peaceful setting."]},{"heading":"Sandbank Adventures","paragraphs":["Visit nearby uninhabited sandbanks for picnics and swimming in crystal-clear waters."]},{"heading":"Beach Highlights","paragraphs":["Maakurathu''s coastal features include:"]},{"heading":"Marine Environment","paragraphs":["The island''s underwater world features:"]},{"heading":"Activities & Experiences","paragraphs":["Maakurathu offers a variety of activities focused on marine adventures, cultural experiences, and relaxation."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef with colorful corals and tropical fish."]},{"heading":"Scuba Diving","paragraphs":["Discover dive sites around Raa Atoll with professional operators."]},{"heading":"Island Hopping Tours","paragraphs":["Visit nearby islands and discover uninhabited sandbanks."]},{"heading":"Traditional Fishing","paragraphs":["Join local fishermen for authentic fishing experiences."]},{"heading":"Cultural Experiences","paragraphs":["Learn about local traditions and daily island life."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll."]},{"heading":"People & Community Life","paragraphs":["Maakurathu is home to a small, close-knit community of approximately 500 residents who maintain traditional Maldivian ways of life. The island''s population is known for their warmth and hospitality."]},{"heading":"Daily Life","paragraphs":["Life on Maakurathu follows traditional rhythms, with fishing and family activities at the heart of daily life. The island maintains a peaceful, unhurried pace."]},{"heading":"Culture & Traditions","paragraphs":["Maakurathu preserves authentic Maldivian cultural traditions including music, dance, and handicrafts. The community celebrates Islamic festivals with enthusiasm."]},{"heading":"Local Economy","paragraphs":["The island''s economy is primarily based on fishing, with a growing tourism sector providing additional opportunities for local families."]}],"island_faqs":[{"question":"How do I get to Maakurathu Island?","answer":"Maakurathu Island can be reached by domestic flight to Ifuru Airport (55 minutes from Male) followed by a 35-minute speedboat ride. Seaplane transfers are also available but depend on weather conditions."},{"question":"What is the best time to visit Maakurathu?","answer":"The best time to visit is during the dry season from December to April when weather conditions are most favorable. However, the island can be visited year-round."},{"question":"What accommodation options are available?","answer":"Maakurathu offers various budget-friendly accommodations including family guesthouses and beachfront properties."},{"question":"What activities are available?","answer":"Maakurathu offers snorkeling, diving excursions, island hopping tours, cultural experiences, and fishing trips."}],"island_nearby_slugs":["rasgetheemu","ungoofaaru","rasmaadhoo","vaadhoo","alifushi","angolhitheemu","dhuvaafaru","fainu","hulhudhuffaaru","inguraidhoo","innamaadhoo","kinolhas","maduvvaree","meedhoo"]}'::jsonb
where node_type = 'location' and slug = 'maakurathu';


-- maalhendhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Noonu Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 900 residents"},{"label":"Size","value":"1.0 km long, 0.6 km wide"},{"label":"Distance from Male","value":"195 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Scenic beauty, stunning beaches, excellent snorkeling"},{"label":"Best For","value":"Nature lovers, photographers, snorkelers, cultural travelers"}],"island_overview":["Maalhendhoo Island is a scenic local island in Noonu Atoll that offers visitors a picturesque glimpse into authentic Maldivian life. This beautiful island combines stunning natural landscapes with a peaceful atmosphere, providing an ideal destination for travelers seeking genuine cultural experiences and breathtaking scenery.","Known for its stunning beaches, crystal-clear lagoons, and excellent house reef, Maalhendhoo provides wonderful opportunities for snorkeling, swimming, and marine exploration. The island''s welcoming community embraces visitors with traditional Maldivian warmth and shares their scenic way of life with genuine hospitality.","What makes Maalhendhoo special is its scenic beauty and picturesque natural setting. Visitors can enjoy breathtaking beaches, explore diverse marine life, and experience traditional island culture while staying in comfortable accommodations that showcase the beautiful Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maalhendhoo Island is strategically located in the northern part of Noonu Atoll, approximately 195 kilometers from Male. This location provides a scenic and picturesque experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to stunning coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the scenic beauty and cultural richness of Noonu Atoll."]},{"heading":"Maalhendhoo: Scenic Paradise & Marine Beauty","paragraphs":["Maalhendhoo Island is blessed with exceptional natural beauty, featuring pristine white sand beaches, crystal-clear turquoise waters, and one of the most scenic marine environments in Noonu Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a picturesque, stunning setting."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Maalhendhoo features breathtaking white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and scenic beach activities."]},{"heading":"Scenic House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers spectacular snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Scenic Community Life","paragraphs":["Experience the picturesque spirit of traditional island life with friendly locals and beautiful Maldivian culture in a stunning community setting."]},{"heading":"Scenic Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and pristine islands around Maalhendhoo for breathtaking tropical paradise experiences with stunning marine life."]},{"heading":"Beach Features","paragraphs":["Maalhendhoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Maalhendhoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Maalhendhoo offers a perfect blend of marine adventures, cultural experiences, and scenic activities. The island''s beautiful environment and picturesque atmosphere provide ideal conditions for various activities in a stunning, breathtaking setting."]},{"heading":"Scenic House Reef Snorkeling","paragraphs":["Explore the stunning house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in beautiful waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby stunning dive sites with professional dive operators offering guided dives and certification courses in scenic marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, pristine sandbanks, and discover the scenic beauty of Noonu Atoll with picturesque exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in scenic community settings."]},{"heading":"Scenic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience beautiful Maldivian island life with scenic cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in stunning waters."]},{"heading":"Community Life & Culture","paragraphs":["Maalhendhoo is home to approximately 900 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and scenic cultural traditions that create a beautiful atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Maalhendhoo follows traditional patterns centered around fishing, family, and community activities. The island maintains a scenic atmosphere where visitors can experience authentic Maldivian culture and customs in their most beautiful, picturesque setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this scenic island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Maalhendhoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and scenic cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Maalhendhoo Island?","answer":"Regular ferry services are also available from Male and nearby islands in Noonu Atoll."},{"question":"What is the best time to visit Maalhendhoo?","answer":"The best time to visit Maalhendhoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more scenic local atmosphere."},{"question":"What accommodation options are available on Maalhendhoo?","answer":"Maalhendhoo offers various budget-friendly accommodations including scenic guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a beautiful setting."},{"question":"What makes Maalhendhoo''s community special?","answer":"Maalhendhoo is known for its scenic and picturesque community atmosphere. The island maintains authentic Maldivian cultural practices while welcoming visitors with warm hospitality. Visitors can experience genuine cultural exchanges and participate in community activities in this beautiful setting."}],"island_nearby_slugs":["foddhoo","manadhoo","velidhoo","miladhoo","maafaru","landhoo","kendhikolhudhoo","magoodhoo","henbandhoo","kudafaree","lhohi"]}'::jsonb
where node_type = 'location' and slug = 'maalhendhoo';


-- maalhos-alif-alif
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Maalhos Island from Male?","answer":"You can reach Maalhos Island from Male by public ferry or speedboat. The public ferry operates three times a week (Sunday, Tuesday, and Thursday), departing from Male at 9:00 AM and arriving at Maalhos around 2:00 PM. Some guesthouses also offer private transfers for a higher fee. It''s recommended to book your transfers in advance, especially during high season."},{"question":"What is the best time to visit Maalhos Island?","answer":"The best time to visit Maalhos Island is during the northeast monsoon (December-April), which generally provides the best overall weather conditions with less rainfall, lower humidity, and calmer seas. This period is ideal for snorkeling, diving, and beach activities. The water visibility is excellent during these months, making it perfect for marine life observation. The southwest monsoon (May-November) may have occasional rain showers but still offers many sunny days, fewer tourists, and lower prices. Water temperature remains warm (27-30C/80-86F) year-round, making Maalhos a viable destination throughout the year."},{"question":"What makes Maalhos different from other local islands in the Maldives?","answer":"Maalhos stands out from other local islands in the Maldives primarily because of its authentic, traditional character that has been well-preserved despite growing tourism. The island is smaller and less developed than popular local islands like Maafushi or Thulusdhoo, offering a more intimate and genuine cultural experience. Maalhos has an exceptional house reef accessible directly from shore, with abundant marine life including turtles and reef sharks. The island''s small population creates a close-knit community atmosphere where visitors can experience traditional Maldivian hospitality and daily life. Additionally, Maalhos is less crowded than more established tourist islands, meaning visitors often have beaches and snorkeling spots almost to themselves."},{"question":"Are there any dress code requirements on Maalhos Island?","answer":"Yes, as Maalhos is a local inhabited island with a Muslim population, visitors are expected to dress modestly in public areas. Both men and women should cover shoulders and knees when walking around the village, visiting shops, or dining in local restaurants. Swimwear (including bikinis) is only permitted at the designated \"bikini beach\" area on the eastern side of the island. When visiting the mosque or religious sites, women should cover their heads with a scarf. These dress code requirements are a sign of respect for local culture and traditions and are generally well-enforced on the island."},{"question":"What marine life can I expect to see while snorkeling around Maalhos?","answer":"Maalhos is renowned for its exceptional marine biodiversity, and snorkelers can expect to see a wide variety of underwater life directly from the beach. Common sightings include colorful reef fish (parrotfish, angelfish, butterflyfish, triggerfish, etc.), blacktip reef sharks, hawksbill and green sea turtles, eagle rays, stingrays, moray eels, octopuses, and various crustaceans. The house reef features healthy coral formations with both hard and soft corals. During certain seasons (typically November to April), manta rays can sometimes be spotted at nearby cleaning stations. The relatively low number of visitors means marine life is less disturbed and more abundant compared to heavily visited areas, providing exceptional snorkeling experiences directly from the shore."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'maalhos-alif-alif';


-- maalhos
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Maalhos Island?","answer":"Public ferry service operates weekly from Male (approximately 9 hours journey time)."},{"question":"What is the best time to visit Maalhos Island?","answer":"The best time to visit Maalhos Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'maalhos';


-- maamendhoo-gaafu-alifu
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Maamendhoo Island?","answer":"Public ferry service operates weekly from Male (approximately 18 hours journey time). Private speedboat transfers can be arranged through guesthouses (approximately 6 hours from Male)."},{"question":"What is the best time to visit Maamendhoo Island?","answer":"The best time to visit Maamendhoo Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas. For whale shark encounters, visit during the southwest monsoon (May to December). Water temperature remains warm (27-30C/80-86F) throughout the year."},{"question":"What makes Maamendhoo different from other local islands in the Maldives?","answer":"Maamendhoo stands out for its exceptional preservation of traditional Maldivian life in a remote setting. Unlike more developed islands, Maamendhoo maintains its authentic character with a community still primarily engaged in traditional fishing. The island offers access to Gaafu Alifu Atoll''s spectacular marine life while providing a genuine cultural experience away from mass tourism."},{"question":"Are there any dress code requirements on Maamendhoo Island?","answer":"As Maamendhoo is a local inhabited island with a Muslim population, visitors are expected to dress modestly in public areas (shoulders and knees covered). Swimwear is only permitted at the designated \"bikini beach.\" When visiting the mosque or religious sites, women should cover their heads. These requirements don''t apply during water activities or at resort day visits."},{"question":"What marine life can I expect to see while snorkeling around Maamendhoo?","answer":"Maamendhoo''s waters offer excellent marine biodiversity, including healthy coral formations with both hard and soft corals. Common sightings include reef sharks (particularly blacktip and whitetip), sea turtles, various ray species, and abundant reef fish. Seasonal visitors include whale sharks (May-December). The house reef provides easy access to this underwater world directly from shore."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'maamendhoo-gaafu-alifu';


-- maamendhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Laamu Atoll, Southern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,100 residents"},{"label":"Size","value":"1.1 km long, 0.6 km wide"},{"label":"Distance from Male","value":"248 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat/ferry"},{"label":"Known For","value":"Traditional culture, handicrafts, cultural preservation, community tourism"},{"label":"Best For","value":"Cultural enthusiasts, tradition seekers, authentic experiences, heritage tourism"}],"island_overview":["Nestled in the pristine waters of Laamu Atoll, Maamendhoo Island offers visitors an authentic journey into traditional Maldivian island life. This charming local island combines stunning natural beauty with deep-rooted cultural traditions, providing an unforgettable experience of genuine island hospitality and heritage.","Maamendhoo is distinguished by its strong cultural identity, beautiful beaches, and vibrant community life. The island has successfully preserved its traditional character while developing sustainable tourism that showcases authentic Maldivian customs, crafts, and daily life to visitors.","What makes Maamendhoo truly special is its commitment to cultural preservation and community-based tourism. Visitors can enjoy excellent snorkeling, participate in traditional activities, and experience genuine Maldivian hospitality while staying in comfortable accommodations that reflect local architectural styles and values."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maamendhoo Island is strategically located in the southern region of Laamu Atoll, approximately 248 kilometers from Male. This excellent location provides easy access while maintaining the authentic island atmosphere that makes it perfect for cultural tourism and traditional experiences.","The island''s position within the atoll offers natural protection and access to excellent snorkeling and diving sites. The surrounding waters are known for their clarity and rich marine biodiversity, while the island itself maintains traditional Maldivian architecture and cultural practices."]},{"heading":"Maamendhoo: Cultural Heritage & Natural Beauty","paragraphs":["Maamendhoo Island is celebrated for its exceptional blend of natural beauty and cultural richness, featuring pristine white sand beaches, crystal-clear waters, and a vibrant community that has preserved traditional Maldivian customs and crafts for generations."]},{"heading":"Traditional Island Beaches","paragraphs":["Maamendhoo features beautiful white sand beaches with traditional palm groves and crystal-clear waters perfect for swimming and relaxation."]},{"heading":"Rich Cultural Heritage","paragraphs":["Experience authentic Maldivian culture through traditional crafts, music, dance, and customs that have been preserved for generations."]},{"heading":"Vibrant Community Life","paragraphs":["Engage with a welcoming community that actively preserves traditional ways of life while embracing sustainable tourism."]},{"heading":"Excellent Marine Environment","paragraphs":["Explore vibrant coral reefs and diverse marine life in the clear waters surrounding this culturally rich island."]},{"heading":"Cultural Features","paragraphs":["Maamendhoo''s cultural attractions include:"]},{"heading":"Natural Environment","paragraphs":["The island''s natural features include:"]},{"heading":"Activities & Cultural Experiences","paragraphs":["Maamendhoo offers a unique range of activities that focus on cultural immersion, traditional crafts, and authentic Maldivian experiences. The island''s strong cultural heritage provides endless opportunities for learning and cultural exchange."]},{"heading":"Traditional Craft Workshops","paragraphs":["Learn traditional Maldivian handicrafts including mat weaving, coconut palm crafts, and traditional woodworking from local artisans."]},{"heading":"Traditional Music & Dance","paragraphs":["Experience authentic Maldivian cultural performances including traditional music, dance, and storytelling by local performers."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef and marine life while learning about traditional fishing methods and marine conservation."]},{"heading":"Traditional Fishing Experiences","paragraphs":["Join local fishermen to learn traditional fishing techniques and experience the island''s maritime heritage firsthand."]},{"heading":"Cultural Heritage Tours","paragraphs":["Take guided tours of the island''s historic sites, traditional buildings, and learn about local customs and traditions."]},{"heading":"Cultural Island Hopping","paragraphs":["Visit nearby islands to compare different cultural traditions and experience the diversity of Laamu Atoll communities."]},{"heading":"People & Cultural Heritage","paragraphs":["Maamendhoo is home to a vibrant community of approximately 1,100 residents who are passionate about preserving and sharing their rich cultural heritage. The island''s population is known for their exceptional craftsmanship, cultural knowledge, and dedication to maintaining traditional Maldivian customs."]},{"heading":"Cultural Preservation","paragraphs":["The community of Maamendhoo has made cultural preservation a priority, actively maintaining traditional crafts, music, dance, and customs. The island serves as a living museum where visitors can experience authentic Maldivian culture in its natural setting."]},{"heading":"Traditional Crafts & Arts","paragraphs":["Maamendhoo is renowned for its traditional handicrafts including mat weaving, coconut palm crafts, traditional woodworking, and boat building. Local artisans are eager to share their knowledge and teach visitors these time-honored skills."]},{"heading":"Community-Based Tourism","paragraphs":["The island has developed a successful model of community-based cultural tourism that benefits local families while preserving cultural heritage. Visitors can participate in daily activities, learn traditional skills, and contribute to the community''s cultural preservation efforts."]}],"island_faqs":[{"question":"How do I get to Maamendhoo Island?","answer":"Seaplane transfers are also available but depend on weather conditions. There''s also a weekly public ferry from Male that takes 14-16 hours."},{"question":"What cultural experiences are available on Maamendhoo?","answer":"Maamendhoo offers traditional craft workshops, cultural performances, heritage tours, traditional fishing experiences, cooking classes, and opportunities to participate in daily community activities. The island is particularly known for its handicraft traditions and cultural preservation efforts."},{"question":"What accommodation options focus on cultural experiences?","answer":"Maamendhoo offers traditional guesthouses and heritage-style accommodations that feature authentic Maldivian architecture and cultural programs."},{"question":"When is the best time to visit for cultural activities?","answer":"Maamendhoo can be visited year-round for cultural experiences. The dry season (December-April) offers the best weather, while cultural festivals and traditional celebrations occur throughout the year. Many cultural workshops and activities are available regardless of season."}],"island_nearby_slugs":["fonadhoo","hithadhoo","isdhoo","kunahandhoo","maavah","mundoo","gan","maabaidhoo","dhanbidhoo"]}'::jsonb
where node_type = 'location' and slug = 'maamendhoo';


-- maamingili
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Dhangethi Island from Male?","answer":"You can reach Dhangethi Island from Male by public ferry or speedboat. The public ferry operates three times a week (Sunday, Tuesday, and Thursday), departing from Male at 9:00 AM and arriving at Dhangethi around 2:30 PM. Some guesthouses also offer private transfers for a higher fee. It''s recommended to book your transfers in advance, especially during high season."},{"question":"What is the best time to visit Dhangethi Island?","answer":"The best time to visit Dhangethi Island is during the northeast monsoon (December-April), which generally provides the best overall weather conditions with less rainfall, lower humidity, and calmer seas. This period is ideal for snorkeling, diving, and beach activities. The water visibility is excellent during these months, making it perfect for marine life observation. The southwest monsoon (May-November) may have occasional rain showers but still offers many sunny days, fewer tourists, and lower prices. For whale shark sightings, the period from January to April is best. Water temperature remains warm (27-30C/80-86F) year-round, making Dhangethi a viable destination throughout the year."},{"question":"What makes Dhangethi different from other local islands in the Maldives?","answer":"Dhangethi stands out from other local islands in the Maldives primarily because of its authentic, traditional character that has been well-preserved despite growing tourism. The island is less developed than popular local islands like Maafushi or Thulusdhoo, offering a more genuine cultural experience. Dhangethi has an exceptional house reef accessible directly from shore, with abundant marine life including turtles and reef sharks. The island''s location in Alifu Dhaalu Atoll provides proximity to famous dive sites and whale shark spotting areas. Additionally, Dhangethi is known for its strong fishing heritage and traditional craftsmanship, particularly boat building. The island is less crowded than more established tourist islands, meaning visitors often have beaches and snorkeling spots almost to themselves."},{"question":"Are there any dress code requirements on Dhangethi Island?","answer":"Yes, as Dhangethi is a local inhabited island with a Muslim population, visitors are expected to dress modestly in public areas. Both men and women should cover shoulders and knees when walking around the village, visiting shops, or dining in local restaurants. Swimwear (including bikinis) is only permitted at the designated \"bikini beach\" area on the eastern side of the island. When visiting the mosque or religious sites, women should cover their heads with a scarf. These dress code requirements are a sign of respect for local culture and traditions and are generally well-enforced on the island."},{"question":"What marine life can I expect to see while snorkeling around Dhangethi?","answer":"Dhangethi is renowned for its exceptional marine biodiversity, and snorkelers can expect to see a wide variety of underwater life directly from the beach. Common sightings include colorful reef fish (parrotfish, angelfish, butterflyfish, triggerfish, etc.), blacktip reef sharks, hawksbill and green sea turtles, eagle rays, stingrays, moray eels, octopuses, and various crustaceans. The house reef features healthy coral formations with both hard and soft corals. The island''s location in Alifu Dhaalu Atoll also provides opportunities for excursions to nearby areas known for manta ray and whale shark sightings (seasonal). The relatively low number of visitors means marine life is less disturbed and more abundant compared to heavily visited areas, providing exceptional snorkeling experiences directly from the shore."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'maamingili';


-- maarandhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Maarandhoo Island?","answer":"Due to the island''s remote location in the northern atolls, direct public ferry services from Male are limited. Most guesthouses can arrange the complete transfer from Male, including the domestic flight and speedboat connection. When planning your journey, remember that weather conditions can occasionally affect flight schedules in this region, so it''s advisable to allow buffer days in your travel plans. The journey to Maarandhoo is part of the adventure, offering beautiful aerial views of the Maldivian atolls during the flight and a chance to experience the stunning blue waters during the speedboat transfer."},{"question":"What makes Maarandhoo''s natural environment unique in the Maldives?","answer":"Maarandhoo''s natural environment stands out in the Maldives because of its unusually lush vegetation and unique mangrove ecosystems. While most Maldivian islands feature primarily coconut palms and beach vegetation, Maarandhoo boasts a more diverse range of plant life, creating a greener landscape. The island''s mangrove areas are particularly special, as these ecosystems are relatively rare on inhabited Maldivian islands. These mangroves provide critical habitat for juvenile fish, crustaceans, and various bird species, creating a biodiversity hotspot. The island also features small freshwater areas that support unique plant species not commonly found on other islands. Maarandhoo''s relatively large size and natural freshwater sources have allowed this diverse ecosystem to flourish. The community has actively worked to preserve these natural features, implementing conservation measures that have maintained the island''s ecological integrity. This combination of diverse vegetation, mangrove ecosystems, and conservation efforts creates a unique natural environment that offers visitors insights into a different aspect of Maldivian ecology beyond the typical beach and reef experience, making Maarandhoo particularly appealing for nature enthusiasts and eco-tourists."},{"question":"What is the best time to visit Maarandhoo Island?","answer":"The best time to visit Maarandhoo Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas. This period is ideal for water activities, with excellent visibility for snorkeling and diving. For those interested in experiencing the island''s natural environment, this dry season also showcases the island''s vegetation at its most vibrant, with many plants flowering and fruiting. The southwest monsoon (May to November) brings occasional rain showers but also lower prices and fewer tourists. This season can actually be an interesting time to visit the mangrove areas, as the increased rainfall enhances these ecosystems. Water temperature remains warm (27-30C/80-86F) throughout the year. Due to Maarandhoo''s northern location, it may experience slightly different weather patterns than southern atolls, with the possibility of brief rain showers even during the dry season. The shoulder months of November and April often offer a good balance of favorable weather and lower visitor numbers."},{"question":"What type of accommodation can I expect on Maarandhoo?","answer":"Accommodation on Maarandhoo is limited and simple, reflecting the island''s authentic character and minimal tourism development. The island offers a small number of family-run guesthouses that provide clean, comfortable rooms with basic amenities including air conditioning, private bathrooms with hot water, and Wi-Fi (though connectivity may be inconsistent). Most accommodations offer full-board packages that include three home-cooked Maldivian meals daily, featuring fresh seafood caught by local fishermen and produce grown on the island. Some local families also offer homestay experiences where guests stay in a room within a family home, providing deeper cultural immersion and the opportunity to participate in daily island activities. A few properties are located near the beach, offering easy access to the island''s beautiful shores. Luxury amenities are limited, and the focus is on authentic experiences rather than high-end facilities. What these accommodations lack in luxury, they make up for in personal service, cultural insights, and genuine hospitality. Visitors should adjust their expectations accordingly and embrace the opportunity to experience authentic island life rather than expecting resort-style amenities."},{"question":"Can I explore the mangrove ecosystems as a visitor to Maarandhoo?","answer":"Yes, visitors to Maarandhoo have excellent opportunities to explore the island''s unique mangrove ecosystems, which is one of the island''s special attractions. Most guesthouses can arrange guided mangrove tours led by knowledgeable local guides who can explain the ecological importance of these areas and identify the various plant and animal species that inhabit them. These tours often involve walking along established paths near the mangroves or using small boats to navigate through the waterways, depending on the tide and specific location. Visitors can observe various bird species, crabs, small fish, and the distinctive mangrove vegetation with its specialized root systems. Some tours focus on the relationship between the mangroves and the surrounding marine environment, explaining how these ecosystems serve as nurseries for many reef fish species. Photography enthusiasts will find plenty of unique subjects in these areas, particularly during early morning or late afternoon when the light is most favorable and wildlife is more active. The local community takes pride in preserving these ecosystems, so guides will ensure that visitors follow appropriate practices to minimize environmental impact. These mangrove explorations provide not just entertainment but educational insights into a critical but often overlooked ecosystem in the Maldives, offering a different perspective on the country''s natural environment beyond its famous beaches and reefs."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'maarandhoo';


-- maaungoodhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Shaviyani Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 900 residents"},{"label":"Size","value":"1.1 km long, 0.7 km wide"},{"label":"Distance from Male","value":"215 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Captivating culture, gorgeous beaches, fantastic traditions"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, tradition seekers, nature lovers"}],"island_overview":["Maaungoodhoo Island is a captivating local island in Shaviyani Atoll that offers visitors a delightful glimpse into traditional Maldivian life in the northern region of the archipelago. This gorgeous island combines natural beauty with a fantastic atmosphere, providing an ideal destination for travelers seeking marvelous cultural experiences and captivating tropical surroundings.","Known for its gorgeous beaches, captivating coral reefs, and fantastic marine biodiversity, Maaungoodhoo provides delightful opportunities for snorkeling, swimming, and underwater exploration. The island''s delightful community embraces visitors with traditional Maldivian warmth and shares their fantastic way of life with captivating hospitality.","What makes Maaungoodhoo special is its captivating natural environment and delightful northern location. Visitors can enjoy gorgeous beaches, explore rich marine ecosystems, and experience fantastic island culture while staying in comfortable accommodations that showcase the captivating Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maaungoodhoo Island is captivatingly located in the northern part of Shaviyani Atoll, approximately 215 kilometers from Male. This location provides a captivating and delightful experience in the northern Maldives, while maintaining fantastic accessibility through seaplane transfers or domestic flights.","The island''s position offers fantastic protection from strong currents while providing access to gorgeous coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Shaviyani Atoll in its most captivating form."]},{"heading":"Maaungoodhoo: Captivating Paradise & Marine Excellence","paragraphs":["Maaungoodhoo Island is blessed with exceptional natural beauty, featuring gorgeous white sand beaches, crystal-clear turquoise waters, and one of the most captivating marine environments in Shaviyani Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a delightful, fantastic setting."]},{"heading":"Gorgeous White Sand Beaches","paragraphs":["Maaungoodhoo features captivating white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and delightful beach activities."]},{"heading":"Captivating House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers delightful snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Delightful Island Community","paragraphs":["Experience the fantastic spirit of traditional northern island life with friendly locals and captivating Maldivian culture in a delightful community setting."]},{"heading":"Fantastic Cultural Heritage","paragraphs":["Discover the island''s rich cultural practices and learn about traditional customs that make this community captivating in the northern Maldives."]},{"heading":"Beach Features","paragraphs":["Maaungoodhoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Maaungoodhoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Maaungoodhoo offers a perfect blend of marine adventures, cultural experiences, and captivating activities. The island''s delightful environment and fantastic atmosphere provide ideal conditions for various activities in a gorgeous, marvelous setting."]},{"heading":"Captivating House Reef Snorkeling","paragraphs":["Explore the delightful house reef directly from the beach, featuring colorful corals, tropical fish, and fantastic underwater visibility in captivating waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby gorgeous dive sites with professional dive operators offering guided dives and certification courses in captivating marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, gorgeous sandbanks, and discover the natural beauty of Shaviyani Atoll with delightful exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in captivating community settings."]},{"heading":"Fantastic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience captivating Maldivian island life with delightful cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy gorgeous sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in captivating waters."]},{"heading":"Community Life & Culture","paragraphs":["Maaungoodhoo is home to approximately 900 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and captivating cultural traditions that create a delightful atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Maaungoodhoo follows traditional patterns centered around fishing, culture, and community activities. The island maintains a captivating atmosphere where visitors can experience delightful Maldivian culture and customs in their most fantastic, marvelous setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and cultural techniques. Visitors can observe and often participate in cultural activities and celebrations in this captivating island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Maaungoodhoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and captivating cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Maaungoodhoo Island?","answer":"Regular inter-island ferry services are also available between Shaviyani Atoll islands."},{"question":"What is the best time to visit Maaungoodhoo?","answer":"The best time to visit Maaungoodhoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more captivating local atmosphere."},{"question":"What accommodation options are available on Maaungoodhoo?","answer":"Maaungoodhoo offers various accommodations including captivating guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a delightful setting."},{"question":"What makes Maaungoodhoo''s culture special?","answer":"Maaungoodhoo is known for its captivating and delightful cultural environment in the northern Maldives. The island maintains traditional Maldivian cultural practices while offering a fantastic atmosphere perfect for marvelous exploration. Visitors can experience gorgeous cultural exchanges and participate in captivating community activities."}],"island_nearby_slugs":["foakaidhoo","feydhoo","feevah","bileffahi","noomaraa","narudhoo","milandhoo","maroshi","lhaimagu","komandoo","kanditheemu","goidhoo","funadhoo"]}'::jsonb
where node_type = 'location' and slug = 'maaungoodhoo';


-- maavah
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Laamu Atoll, Southern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,200 residents"},{"label":"Size","value":"1.2 km long, 0.7 km wide"},{"label":"Distance from Male","value":"250 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat/ferry"},{"label":"Known For","value":"Beautiful beaches, house reef, traditional culture, fishing heritage"},{"label":"Best For","value":"Cultural enthusiasts, snorkelers, budget travelers, nature lovers"}],"island_overview":["Situated in the pristine waters of Laamu Atoll, Maavah Island offers visitors an authentic glimpse into traditional Maldivian island life. This charming local island combines stunning natural beauty with rich cultural heritage, providing an unforgettable tropical paradise experience away from the crowds.","Maavah is distinguished by its beautiful white sand beaches, excellent house reef, and strong community spirit. The island has successfully preserved its traditional character while developing sustainable tourism that benefits the local community and protects the pristine marine environment.","What makes Maavah truly special is its perfect combination of natural beauty and cultural authenticity. Visitors can enjoy excellent snorkeling, experience genuine Maldivian hospitality, and relax on some of the most beautiful beaches in the southern Maldives, all while staying in comfortable, budget-friendly accommodations."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maavah Island is strategically located in the southern region of Laamu Atoll, approximately 250 kilometers from Male. This excellent location provides the perfect balance of accessibility and tranquility, offering visitors an authentic island experience in a pristine tropical setting.","The island''s position within the atoll provides natural protection from strong currents while offering easy access to some of the best snorkeling and diving sites in the Maldives. The surrounding waters are known for their clarity, rich marine biodiversity, and healthy coral ecosystems."]},{"heading":"Maavah: Natural Beauty & Marine Heritage","paragraphs":["Maavah Island is celebrated for its exceptional natural beauty, featuring pristine white sand beaches, crystal-clear turquoise waters, and a vibrant house reef that''s perfect for snorkeling. The island offers an authentic tropical paradise experience with excellent marine biodiversity and stunning coastal landscapes."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Maavah features some of the most beautiful beaches in Laamu Atoll, with soft white sand and crystal-clear waters perfect for swimming and relaxation."]},{"heading":"Vibrant House Reef","paragraphs":["The island''s house reef is easily accessible from shore and offers excellent snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Rich Fishing Heritage","paragraphs":["Experience the island''s strong fishing traditions and join local fishermen for authentic fishing experiences using traditional methods."]},{"heading":"Vibrant Island Community","paragraphs":["Engage with the friendly local community and experience authentic Maldivian culture, traditions, and warm hospitality."]},{"heading":"Beach Features","paragraphs":["Maavah''s coastal attractions include:"]},{"heading":"Marine Life","paragraphs":["The island''s underwater ecosystem features:"]},{"heading":"Activities & Experiences","paragraphs":["Maavah offers an excellent variety of activities that showcase the best of Maldivian marine life, cultural heritage, and natural beauty. The island''s rich fishing traditions and pristine environment provide endless opportunities for adventure and cultural discovery."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility."]},{"heading":"Traditional Fishing Experiences","paragraphs":["Join local fishermen for authentic fishing experiences using traditional hand lines and learn about the island''s rich fishing heritage."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover world-class dive sites around Laamu Atoll with experienced dive operators offering courses and guided underwater adventures."]},{"heading":"Island Hopping Tours","paragraphs":["Visit nearby islands and discover uninhabited sandbanks, each offering unique experiences and pristine natural beauty."]},{"heading":"Cultural Immersion","paragraphs":["Engage with the local community, learn traditional crafts, and experience authentic Maldivian customs and daily island life."]},{"heading":"Dolphin Watching Cruises","paragraphs":["Experience magical dolphin watching cruises during sunset, often combined with traditional dhoni sailing and photography opportunities."]},{"heading":"People & Community Life","paragraphs":["Maavah is home to a vibrant community of approximately 1,200 residents who have successfully preserved traditional Maldivian culture while embracing sustainable tourism. The island''s population is known for their exceptional hospitality, strong fishing traditions, and deep connection to the ocean."]},{"heading":"Island Heritage","paragraphs":["Daily life on Maavah revolves around the natural rhythms of island living, with the community engaging in fishing, small-scale agriculture, and tourism-related activities. The island has a rich maritime heritage and maintains traditional fishing practices that have been passed down through generations."]},{"heading":"Cultural Traditions","paragraphs":["Maavah preserves authentic Maldivian cultural traditions including traditional music, dance, and handicrafts. The community celebrates Islamic festivals with great enthusiasm and maintains traditional practices such as dhoni boat building, traditional fishing techniques, and local cuisine preparation."]},{"heading":"Sustainable Development","paragraphs":["The island has embraced sustainable tourism practices that benefit the local community while preserving the natural environment and cultural heritage. Many families participate in tourism through guesthouses, restaurants, and tour services, creating economic opportunities while maintaining authenticity."]}],"island_faqs":[{"question":"How do I get to Maavah Island?","answer":"Seaplane transfers are also available but depend on weather conditions. There''s also a weekly public ferry from Male that takes 14-16 hours."},{"question":"What is the best time to visit Maavah?","answer":"The best time to visit Maavah is during the dry season from December to April when weather conditions are most favorable with minimal rainfall and calm seas. However, the island can be visited year-round, with the wet season (May-November) offering fewer crowds and more competitive accommodation rates."},{"question":"What accommodation options are available on Maavah?","answer":"Maavah offers various budget-friendly and mid-range accommodations including traditional family guesthouses and beachfront properties. Most accommodations feature air conditioning, private bathrooms, and meal packages."},{"question":"What activities are available on Maavah?","answer":"Maavah offers excellent house reef snorkeling, traditional fishing experiences, diving excursions, island hopping tours, cultural experiences, and dolphin watching cruises. The island is particularly known for its rich fishing heritage and authentic cultural experiences with the local community."}],"island_nearby_slugs":["fonadhoo","hithadhoo","isdhoo","kunahandhoo","gan","maabaidhoo","mundoo","dhanbidhoo","maamendhoo"]}'::jsonb
where node_type = 'location' and slug = 'maavah';


-- madaveli
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Madaveli Island?","answer":"Public ferry service operates weekly from Male (approximately 18 hours journey time). Private speedboat transfers can be arranged through guesthouses (approximately 6 hours from Male)."},{"question":"What is the best time to visit Madaveli Island?","answer":"The best time to visit Madaveli Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas. For whale shark encounters, visit during the southwest monsoon (May to December). Water temperature remains warm (27-30C/80-86F) throughout the year."},{"question":"What makes Madaveli different from other local islands in the Maldives?","answer":"Madaveli stands out for its exceptional preservation of traditional Maldivian life in a remote setting. Unlike more developed islands, Madaveli maintains its authentic character with a community still primarily engaged in traditional fishing. The island offers access to Gaafu Dhaalu Atoll''s spectacular marine life while providing a genuine cultural experience away from mass tourism."},{"question":"Are there any dress code requirements on Madaveli Island?","answer":"As Madaveli is a local inhabited island with a Muslim population, visitors are expected to dress modestly in public areas (shoulders and knees covered). Swimwear is only permitted at the designated \"bikini beach.\" When visiting the mosque or religious sites, women should cover their heads. These requirements don''t apply during water activities or at resort day visits."},{"question":"What marine life can I expect to see while snorkeling around Madaveli?","answer":"Madaveli''s waters offer excellent marine biodiversity, including healthy coral formations with both hard and soft corals. Common sightings include reef sharks (particularly blacktip and whitetip), sea turtles, various ray species, and abundant reef fish. Seasonal visitors include whale sharks (May-December). The house reef provides easy access to this underwater world directly from shore."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'madaveli';


-- madifushi
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Thaa Atoll, Central Maldives"},{"label":"Island Type","value":"Inhabited Local Island with Airport"},{"label":"Population","value":"Approximately 2,500 residents"},{"label":"Size","value":"2.1 km long, 1.3 km wide"},{"label":"Distance from Male","value":"215 km"},{"label":"Transfer Options","value":"Domestic flight or seaplane"},{"label":"Known For","value":"Exceptional culture, amazing beaches, airport gateway"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, convenient access"}],"island_overview":["Thimarafushi Island is an exceptional local island in Thaa Atoll that offers visitors a vibrant glimpse into traditional Maldivian life. This remarkable island combines natural beauty with an energetic atmosphere, providing an ideal destination for travelers seeking exciting cultural experiences and amazing tropical surroundings.","Known for its gorgeous beaches, exceptional coral reefs, and excellent marine biodiversity, Thimarafushi provides wonderful opportunities for snorkeling, swimming, and underwater exploration. The island''s vibrant community embraces visitors with traditional Maldivian warmth and shares their dynamic way of life with exceptional hospitality.","What makes Thimarafushi special is its exceptional natural environment and vibrant island setting. Visitors can enjoy amazing beaches, explore rich marine ecosystems, and experience dynamic island culture while staying in comfortable accommodations that showcase the exceptional Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Thimarafushi Island is strategically located in the central part of Thaa Atoll, approximately 215 kilometers from Male. This location provides an exceptional and vibrant experience while serving as the main gateway to Thaa Atoll through its domestic airport, making it highly accessible for travelers.","The island''s position offers excellent protection from strong currents while providing access to amazing coral reefs and diverse marine ecosystems. Its location and airport facilities make it an ideal base for exploring the natural beauty and cultural richness of Thaa Atoll in its most exceptional form."]},{"heading":"Thimarafushi: Exceptional Paradise & Marine Excellence","paragraphs":["Thimarafushi Island is blessed with exceptional natural beauty, featuring amazing white sand beaches, crystal-clear turquoise waters, and one of the most exceptional marine environments in Thaa Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a vibrant, dynamic setting."]},{"heading":"Amazing White Sand Beaches","paragraphs":["Thimarafushi features exceptional white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and dynamic beach activities."]},{"heading":"Exceptional House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers vibrant snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Vibrant Island Community","paragraphs":["Experience the dynamic spirit of traditional island life with friendly locals and exceptional Maldivian culture in a vibrant community setting."]},{"heading":"Dynamic Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and amazing islands around Thimarafushi for exceptional tropical paradise experiences with rich marine life."]},{"heading":"Beach Features","paragraphs":["Thimarafushi''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Thimarafushi feature:"]},{"heading":"Activities & Experiences","paragraphs":["Thimarafushi offers a perfect blend of marine adventures, cultural experiences, and exceptional activities. The island''s vibrant environment and dynamic atmosphere provide ideal conditions for various activities in an amazing, energetic setting with convenient access to the entire atoll."]},{"heading":"Exceptional House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in exceptional waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby amazing dive sites with professional dive operators offering guided dives and certification courses in exceptional marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, amazing sandbanks, and discover the natural beauty of Thaa Atoll with vibrant exploration opportunities from the airport hub."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in exceptional community settings."]},{"heading":"Dynamic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience exceptional Maldivian island life with vibrant cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy amazing sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in exceptional waters."]},{"heading":"Community Life & Culture","paragraphs":["Thimarafushi is home to approximately 2,500 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism and modern connectivity through the island''s airport. The island''s community is known for their exceptional friendliness, hospitality, and exceptional cultural traditions that create a vibrant atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Thimarafushi follows traditional patterns centered around fishing, family, and community activities, enhanced by the island''s role as a transportation hub. The island maintains an exceptional atmosphere where visitors can experience vibrant Maldivian culture and customs in their most dynamic, energetic setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this exceptional island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Thimarafushi has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and exceptional cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Thimarafushi Island?","answer":"The island serves as the main gateway to Thaa Atoll with its domestic airport, making it easily accessible for travelers."},{"question":"What is the best time to visit Thimarafushi?","answer":"The best time to visit Thimarafushi is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more exceptional local atmosphere."},{"question":"What accommodation options are available on Thimarafushi?","answer":"Thimarafushi offers various accommodations including exceptional guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a vibrant setting."},{"question":"What makes Thimarafushi''s accessibility special?","answer":"Thimarafushi is known for its exceptional accessibility as the main gateway to Thaa Atoll with its domestic airport. The island maintains traditional Maldivian cultural practices while offering a dynamic atmosphere perfect for energetic exploration with convenient connections to other islands in the atoll."}],"island_nearby_slugs":["guraidhoo","gaadhiffushi","dhiyamigili","burunee","vilufushi","veymandoo","vandhoo","thimarafushi","omadhoo","kinbidhoo","kandoodhoo","hirilandhoo"]}'::jsonb
where node_type = 'location' and slug = 'madifushi';


