update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Meemu Atoll, Central Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 900 residents"},{"label":"Size","value":"1.1 km long, 0.5 km wide"},{"label":"Distance from Male","value":"135 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat (1.5 hours total)"},{"label":"Known For","value":"Pristine beaches, fishing culture, authentic experiences"},{"label":"Best For","value":"Culture seekers, nature lovers, budget travelers"}],"island_overview":["Nestled in the pristine waters of Meemu Atoll, Dhiggaru Island offers visitors an authentic Maldivian experience away from the crowds. This charming island combines natural beauty with traditional island life.","Dhiggaru is known for its long stretches of white sand beaches, excellent fishing culture, and peaceful atmosphere. The island maintains its traditional character while welcoming visitors with genuine hospitality.","What makes Dhiggaru special is its unspoiled environment, rich marine biodiversity, and the opportunity to experience local culture in a relaxed setting."],"island_sections":[{"heading":"Location & Map","paragraphs":["Dhiggaru Island is located in the central part of Meemu Atoll, approximately 135 kilometers from Male. This location offers a peaceful retreat while maintaining access to excellent marine environments.","The island''s position provides natural protection from strong currents while offering access to vibrant coral reefs and abundant marine life."]},{"heading":"Dhiggaru: Natural Beauty & Marine Life","paragraphs":["Dhiggaru Island boasts stunning natural beauty with powder-soft white sand beaches, crystal-clear turquoise waters, and healthy coral reefs teeming with marine life."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Dhiggaru features some of the most beautiful beaches in Meemu Atoll, perfect for relaxation and beach walks."]},{"heading":"Excellent Snorkeling","paragraphs":["The island''s house reef offers easy access to colorful coral formations and diverse marine life."]},{"heading":"Authentic Fishing Culture","paragraphs":["Experience the traditional fishing lifestyle that has sustained Dhiggaru for generations."]},{"heading":"Sandbank Visits","paragraphs":["Explore nearby uninhabited sandbanks for the ultimate tropical island experience."]},{"heading":"Beach Highlights","paragraphs":["Dhiggaru''s coastal features include:"]},{"heading":"Marine Environment","paragraphs":["The island''s underwater world features:"]},{"heading":"Activities & Experiences","paragraphs":["Dhiggaru offers a variety of activities focused on marine adventures, cultural experiences, and relaxation."]},{"heading":"Snorkeling Adventures","paragraphs":["Explore vibrant coral reefs teeming with tropical fish."]},{"heading":"Scuba Diving","paragraphs":["Discover world-class dive sites in Meemu Atoll."]},{"heading":"Island Hopping","paragraphs":["Visit nearby islands to experience different aspects of the Maldives."]},{"heading":"Fishing Excursions","paragraphs":["Join local fishermen for traditional fishing experiences."]},{"heading":"Cultural Experiences","paragraphs":["Learn about traditional Maldivian crafts and daily life."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy breathtaking sunsets over the Indian Ocean."]},{"heading":"People & Community Life","paragraphs":["Dhiggaru is home to a close-knit community of approximately 900 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism."]},{"heading":"Daily Life","paragraphs":["Life on Dhiggaru revolves around fishing, tourism, and community activities. The island has a peaceful rhythm that reflects traditional Maldivian values."]},{"heading":"Culture & Traditions","paragraphs":["Dhiggaru preserves authentic Maldivian cultural traditions including music, dance, and handicrafts. The community celebrates Islamic festivals with enthusiasm."]}],"island_faqs":[{"question":"How do I get to Dhiggaru Island?","answer":"Dhiggaru can be reached by domestic flight to Kadhdhoo Airport (1 hour from Male) followed by a 30-minute speedboat ride. Seaplane transfers are also available but depend on weather conditions."},{"question":"What is the best time to visit Dhiggaru?","answer":"The best time is during the dry season from December to April, but Dhiggaru can be visited year-round."}],"island_nearby_slugs":["kolhufushi","muli","maduvvaree","raimmandhoo","dhiggaru","naalaafushi","veyvah"]}'::jsonb
where node_type = 'location' and slug = 'maduvvaree-meemu';


