update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Noonu Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,100 residents"},{"label":"Size","value":"1.1 km long, 0.7 km wide"},{"label":"Distance from Male","value":"200 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Pristine beauty, magnificent beaches, excellent snorkeling"},{"label":"Best For","value":"Nature enthusiasts, photographers, snorkelers, cultural travelers"}],"island_overview":["Magoodhoo Island is a pristine local island in Noonu Atoll that offers visitors an unspoiled glimpse into authentic Maldivian life. This magnificent island combines stunning natural beauty with an untouched atmosphere, providing an ideal destination for travelers seeking genuine cultural experiences and pristine natural splendor.","Known for its beautiful beaches, crystal-clear lagoons, and excellent house reef, Magoodhoo provides exceptional opportunities for snorkeling, swimming, and marine exploration. The island''s welcoming community embraces visitors with traditional Maldivian warmth and shares their pristine way of life with genuine hospitality.","What makes Magoodhoo special is its pristine beauty and unspoiled natural setting. Visitors can enjoy magnificent beaches, explore diverse marine life, and experience traditional island culture while staying in comfortable accommodations that showcase the pristine Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Magoodhoo Island is strategically located in the northern part of Noonu Atoll, approximately 200 kilometers from Male. This location provides a pristine and magnificent experience while maintaining good accessibility to the capital and international airport through various transfer 